from pathlib import Path
import re


def replace_once(path, old, new, label):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: {label}: expected 1, found {count}')
    p.write_text(text.replace(old, new), encoding='utf-8')


def regex_once(path, pattern, replacement, label, flags=re.S):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    new, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise SystemExit(f'{path}: {label}: expected 1, found {count}')
    p.write_text(new, encoding='utf-8')

# Format-neutral parameter/readiness contract.
regex_once(
    'tests/test_realtime.cpp',
    r'void testParameterContract\(\) \{.*?\n\}\n\nvoid testCaptureDiagnosticsAndValidation',
    '''void testParameterContract() {\n  const auto& parameters = tonetrace::parameterDescriptors();\n  require(parameters.size() == 23, "The generic parameter inventory is incomplete");\n  const std::vector<std::string> expectedOrder{\n      "Capture Reference", "Learn Target", "Correct Target",\n      "Freeze Correction", "Workflow Stage", "Status", "Last Action",\n      "Match Mode", "Maximum Correction", "Full Correction Range",\n      "Correction Strength", "Correction Resolution",\n      "Correction Range Low", "Correction Range High",\n      "Correction Q / Sharpness", "Correction Gain",\n      "Emergency Clip Guard", "Confidence Tone Volume",\n      "Capture Confidence", "Curve Drift", "Capture Time",\n      "Tone Notifications", "Bypass"};\n  std::set<std::uint32_t> identifiers;\n  std::set<std::string> names;\n  for (std::size_t index = 0; index < parameters.size(); ++index) {\n    const auto& parameter = parameters[index];\n    require(parameter.name != nullptr && std::string(parameter.name).size() >= 3,\n            "A parameter lacks an accessible name");\n    require(std::isfinite(parameter.minimum) && std::isfinite(parameter.maximum) &&\n                std::isfinite(parameter.defaultValue) &&\n                parameter.maximum >= parameter.minimum &&\n                parameter.defaultValue >= parameter.minimum &&\n                parameter.defaultValue <= parameter.maximum,\n            "A parameter has an invalid range or default");\n    require(identifiers.insert(static_cast<std::uint32_t>(parameter.id)).second,\n            "A stable parameter identifier is duplicated");\n    require(names.insert(parameter.name).second, "A parameter name is duplicated");\n    require(parameter.name == expectedOrder[index],\n            "The universal parameter order changed");\n\n    const bool hiddenTelemetry =\n        parameter.id == tonetrace::ParameterId::LastCommand ||\n        parameter.id == tonetrace::ParameterId::Confidence ||\n        parameter.id == tonetrace::ParameterId::CurveDriftDb ||\n        parameter.id == tonetrace::ParameterId::CaptureSeconds;\n    if (hiddenTelemetry) {\n      require(parameter.readOnly && !parameter.automatable,\n              "Fast/internal telemetry leaked back into host automation");\n    } else {\n      require(parameter.automatable,\n              "A host-visible control/state is no longer exposed to OSARA");\n    }\n  }\n  const auto mode = std::find_if(\n      parameters.begin(), parameters.end(), [](const auto& parameter) {\n        return parameter.id == tonetrace::ParameterId::MatchMode;\n      });\n  require(mode != parameters.end() && mode->defaultValue == 1.0,\n          "A fresh instance no longer starts in Voice Match Mode");\n\n  using P = tonetrace::WorkflowPhase;\n  require(!tonetrace::referenceCaptureCanAdvance(P::CapturingReference, 0, false, false) &&\n              tonetrace::referenceCaptureCanAdvance(P::CapturingReference, 1, false, false) &&\n              tonetrace::referenceCaptureCanAdvance(P::CapturingReference, 0, true, false) &&\n              tonetrace::referenceCaptureCanAdvance(P::Ready, 0, false, true) &&\n              !tonetrace::referenceCaptureCanAdvance(P::CapturingTarget, 1, false, false),\n          "Reference readiness does not follow the shared Low/full/import rule");\n  require(!tonetrace::targetCaptureCanCorrect(P::CapturingTarget, 0, false, false) &&\n              tonetrace::targetCaptureCanCorrect(P::CapturingTarget, 1, false, false) &&\n              tonetrace::targetCaptureCanCorrect(P::CapturingTarget, 0, true, false) &&\n              tonetrace::targetCaptureCanCorrect(P::Ready, 0, false, true) &&\n              !tonetrace::targetCaptureCanCorrect(P::CapturingReference, 1, false, false),\n          "Target readiness does not follow the shared Low/full/import rule");\n  std::cout << "universal parameter and workflow-readiness contract: passed\\n";\n}\n\nvoid testCaptureDiagnosticsAndValidation''',
    'replace old parameter contract')

p = Path('tests/test_clap.cpp')
text = p.read_text(encoding='utf-8')

old_constants = '''constexpr clap_id kWorkflow = 100;\nconstexpr clap_id kMatchMode = 110;'''
new_constants = '''constexpr clap_id kRetiredWorkflow = 100;\nconstexpr clap_id kWorkflowStage = 280;\nconstexpr clap_id kCaptureReferenceCommand = 281;\nconstexpr clap_id kLearnTargetCommand = 282;\nconstexpr clap_id kCorrectTargetCommand = 283;\nconstexpr clap_id kFreezeCorrectionCommand = 284;\nconstexpr clap_id kMatchMode = 110;'''
if text.count(old_constants) != 1: raise SystemExit('CLAP constants block mismatch')
