# Add one authoritative action->parameter mapping for all test paths.
anchor = '''struct InputEvents {\n  clap_input_events_t events_interface{};'''
insert = '''clap_id workflowCommandParameter(int action) {\n  switch (action) {\n    case 1: return kCaptureReferenceCommand;\n    case 2: return kLearnTargetCommand;\n    case 3: return kCorrectTargetCommand;\n    case 4: return kFreezeCorrectionCommand;\n    default: return CLAP_INVALID_ID;\n  }\n}\n\nint expectedStageAfterAction(int action) {\n  switch (action) {\n    case 1: return 1;\n    case 2: return 2;\n    case 3: return 2;  // analysis must succeed before Stage advances to Preview\n    case 4: return 4;\n    default: return -1;\n  }\n}\n\nbool isHiddenTelemetry(clap_id id) {\n  return id == kLastCommand || id == kConfidence || id == kCurveDrift ||\n         id == kCaptureTime;\n}\n\nstruct InputEvents {\n  clap_input_events_t events_interface{};'''
if text.count(anchor) != 1: raise SystemExit('InputEvents anchor mismatch')
text = text.replace(anchor, insert)

old_command = '''  void command(std::uint32_t time, int value) {\n    parameter(time, kWorkflow, value);\n  }'''
new_command = '''  void command(std::uint32_t time, int action, double requested = 1.0) {\n    if (action == 0) return;\n    const clap_id id = workflowCommandParameter(action);\n    require(id != CLAP_INVALID_ID, "invalid workflow action in test");\n    parameter(time, id, requested);\n  }'''
if text.count(old_command) != 1: raise SystemExit('InputEvents command mismatch')
text = text.replace(old_command, new_command)

old_helper = '''double processCommand(const clap_plugin_t* plugin,\n                      int command,\n                      int expectedPersisted = -1,\n                      std::size_t frames = 64) {\n  std::array<std::vector<float>, 2> input{\n      std::vector<float>(frames), std::vector<float>(frames)};\n  std::array<std::vector<float>, 2> output;\n  InputEvents events;\n  OutputEvents responses;\n  events.command(0, command);\n  process(plugin, input, output, &events, &responses);\n  const auto* params = static_cast<const clap_plugin_params_t*>(\n      plugin->get_extension(plugin, CLAP_EXT_PARAMS));\n  double persisted = -1.0;\n  if (expectedPersisted < 0) expectedPersisted = command;\n  require(params != nullptr && params->get_value(plugin, kWorkflow, &persisted) &&\n              static_cast<int>(persisted) == expectedPersisted,\n          "workflow step did not persist at the requested value");\n  double energy = 0.0;\n  for (const auto& channel : output) {\n    for (const float sample : channel) energy += std::abs(sample);\n  }\n  return energy;\n}'''
new_helper = '''double processCommand(const clap_plugin_t* plugin,\n                      int action,\n                      int expectedStage = -1,\n                      std::size_t frames = 64,\n                      double requested = 1.0) {\n  std::array<std::vector<float>, 2> input{\n      std::vector<float>(frames), std::vector<float>(frames)};\n  std::array<std::vector<float>, 2> output;\n  InputEvents events;\n  OutputEvents responses;\n  events.command(0, action, requested);\n  process(plugin, input, output, &events, &responses);\n  const auto* params = static_cast<const clap_plugin_params_t*>(\n      plugin->get_extension(plugin, CLAP_EXT_PARAMS));\n  if (expectedStage < 0) expectedStage = expectedStageAfterAction(action);\n  if (action != 0) {\n    double commandValue = -1.0;\n    require(params != nullptr &&\n                params->get_value(plugin, workflowCommandParameter(action),\n                                  &commandValue) &&\n                commandValue == 0.0,\n            "momentary workflow action did not return immediately to Ready");\n  }\n  require(expectedStage < 0 ||\n              static_cast<int>(plugin == nullptr ? -1.0 : [&] {\n                double stage = -1.0;\n                require(params->get_value(plugin, kWorkflowStage, &stage),\n                        "Workflow Stage query failed");\n                return stage;\n              }()) == expectedStage,\n          "Workflow Stage disagrees with the engine state after an action");\n  double energy = 0.0;\n  for (const auto& channel : output) {\n    for (const float sample : channel) energy += std::abs(sample);\n  }\n  return energy;\n}'''
if text.count(old_helper) != 1: raise SystemExit('processCommand helper mismatch')
text = text.replace(old_helper, new_helper)

old_signal_assert = '''    require(std::none_of(responses.events.begin(), responses.events.end(),\n                         [](const auto& event) {\n                           return event.param_id == kWorkflow;\n                         }),\n            "audio emitted an unexpected workflow step event");'''
new_signal_assert = '''    require(std::none_of(responses.events.begin(), responses.events.end(),\n                         [](const auto& event) {\n                           return isHiddenTelemetry(event.param_id);\n                         }),\n            "live capture telemetry leaked into the host event stream");'''
if text.count(old_signal_assert) != 1: raise SystemExit('processSignal assertion mismatch')
text = text.replace(old_signal_assert, new_signal_assert)

# Every old read of the sticky slider is now a read of authoritative Stage.
text = text.replace('instance.parameter(kWorkflow)', 'instance.parameter(kWorkflowStage)')
text = text.replace('snapshotRestored.parameter(kWorkflow)', 'snapshotRestored.parameter(kWorkflowStage)')

old_inventory = '''    require(instance.params->count(instance.plugin) == 19,\n            "unexpected parameter count");\n    std::vector<clap_id> ids;\n    std::vector<clap_id> orderedIds;\n    for (uint32_t index = 0; index < instance.params->count(instance.plugin);\n         ++index) {\n      clap_param_info_t info{};\n      require(instance.params->get_info(instance.plugin, index, &info),\n              "parameter descriptor query failed");\n      require(info.name[0] != '\\0' && info.min_value <= info.default_value &&\n                  info.default_value <= info.max_value,\n              "invalid parameter descriptor");\n      require((info.flags & CLAP_PARAM_IS_AUTOMATABLE) != 0,\n              "a parameter is hidden from OSARA because it is not automatable");\n      ids.push_back(info.id);\n      orderedIds.push_back(info.id);\n    }\n    std::sort(ids.begin(), ids.end());\n    require(std::adjacent_find(ids.begin(), ids.end()) == ids.end(),\n            "duplicate parameter id");\n    const std::vector<clap_id> expectedOrder{\n        100, 230, 195, 110, 160, 170, 120, 130, 140, 150,\n        190, 180, 270, 250, 200, 210, 220, 240, 260};\n    require(orderedIds == expectedOrder,\n            "generic parameter order no longer matches the frozen accessible design");\n    char accessibleText[128]{};\n    double parsedValue = -1.0;\n    require(instance.params->value_to_text(instance.plugin, kWorkflow, 2.0,\n                                           accessibleText,\n                                           sizeof(accessibleText)) &&\n                std::strcmp(accessibleText,\n                            "Save Reference and Learn Target") == 0 &&\n                instance.params->text_to_value(instance.plugin, kWorkflow,\n                                               "Capture Reference",\n                                               &parsedValue) &&\n                parsedValue == 1.0,\n            "workflow labels are not round-trippable through the generic host interface");'''
new_inventory = '''    require(instance.params->count(instance.plugin) == 23,\n            "unexpected parameter count");\n    std::vector<clap_id> ids;\n    std::vector<clap_id> orderedIds;\n    for (uint32_t index = 0; index < instance.params->count(instance.plugin);\n         ++index) {\n      clap_param_info_t info{};\n      require(instance.params->get_info(instance.plugin, index, &info),\n              "parameter descriptor query failed");\n      require(info.name[0] != '\\0' && info.min_value <= info.default_value &&\n                  info.default_value <= info.max_value,\n              "invalid parameter descriptor");\n      const bool hiddenTelemetry = isHiddenTelemetry(info.id);\n      const bool visibleFeedback = info.id == kWorkflowStage || info.id == kStatus;\n      if (hiddenTelemetry) {\n        require((info.flags & CLAP_PARAM_IS_READONLY) != 0 &&\n                    (info.flags & CLAP_PARAM_IS_HIDDEN) != 0 &&\n                    (info.flags & CLAP_PARAM_IS_AUTOMATABLE) == 0,\n                "internal telemetry is still exposed as host automation");\n      } else if (visibleFeedback) {\n        require((info.flags & CLAP_PARAM_IS_READONLY) != 0 &&\n                    (info.flags & CLAP_PARAM_IS_HIDDEN) == 0 &&\n                    (info.flags & CLAP_PARAM_IS_AUTOMATABLE) != 0,\n                "authoritative Stage/Status feedback is not visible to OSARA");\n      } else {\n        require((info.flags & CLAP_PARAM_IS_READONLY) == 0 &&\n                    (info.flags & CLAP_PARAM_IS_HIDDEN) == 0 &&\n                    (info.flags & CLAP_PARAM_IS_AUTOMATABLE) != 0,\n                "a writable control is not universally host-visible");\n      }\n      if (info.id == kCaptureReferenceCommand || info.id == kLearnTargetCommand ||\n          info.id == kCorrectTargetCommand || info.id == kFreezeCorrectionCommand) {\n        require((info.flags & CLAP_PARAM_IS_STEPPED) != 0 &&\n                    (info.flags & CLAP_PARAM_IS_ENUM) != 0,\n                "a workflow action is not a discrete momentary host control");\n      }\n      ids.push_back(info.id);\n      orderedIds.push_back(info.id);\n    }\n    std::sort(ids.begin(), ids.end());\n    require(std::adjacent_find(ids.begin(), ids.end()) == ids.end(),\n            "duplicate parameter id");\n    const std::vector<clap_id> expectedOrder{\n        281, 282, 283, 284, 280, 230, 195, 110, 160, 170, 120, 130,\n        140, 150, 190, 180, 270, 250, 200, 210, 220, 240, 260};\n    require(orderedIds == expectedOrder,\n            "generic parameter order no longer matches the universal design");\n    char accessibleText[128]{};\n    double parsedValue = -1.0;\n    double retiredValue = 0.0;\n    require(instance.params->value_to_text(instance.plugin, kLearnTargetCommand, 0.0,\n                                           accessibleText, sizeof(accessibleText)) &&\n                std::strcmp(accessibleText, "Ready") == 0 &&\n                instance.params->text_to_value(instance.plugin, kLearnTargetCommand,\n                                               "Requested", &parsedValue) &&\n                parsedValue == 1.0 &&\n                instance.params->value_to_text(instance.plugin, kWorkflowStage, 2.0,\n                                               accessibleText, sizeof(accessibleText)) &&\n                std::strcmp(accessibleText, "Learning Target") == 0 &&\n                !instance.params->get_value(instance.plugin, kRetiredWorkflow,\n                                            &retiredValue),\n            "new workflow actions/stage did not replace the retired sticky slider cleanly");'''
if text.count(old_inventory) != 1: raise SystemExit('parameter inventory block mismatch')
text = text.replace(old_inventory, new_inventory)

old_readonly = '''      require(instance.parameter(kConfidence) == 0.0 &&\n                  std::any_of(restoredValue.events.begin(),\n                              restoredValue.events.end(),\n                              [](const auto& event) {\n                                return event.param_id == kConfidence &&\n                                       event.value == 0.0;\n                              }),\n              "a moved read-only status value did not self-restore for the host");'''
new_readonly = '''      require(instance.parameter(kConfidence) == 0.0 &&\n                  std::none_of(restoredValue.events.begin(),\n                               restoredValue.events.end(),\n                               [](const auto& event) {\n                                 return event.param_id == kConfidence;\n                               }),\n              "a host write made hidden telemetry writable or emitted telemetry traffic");'''
if text.count(old_readonly) != 1: raise SystemExit('readonly telemetry block mismatch')
text = text.replace(old_readonly, new_readonly)

# Replace the first host-flush workflow test with a fractional momentary action
# and add a wrong-stage non-destructive rejection before capture starts.
old_first_flush = '''    std::array<std::vector<float>, 2> gatedSilence{\n        std::vector<float>(48000 * 2), std::vector<float>(48000 * 2)};\n    flushParameter(instance.plugin, kWorkflow, 1.0);\n    require(instance.parameter(kWorkflowStage) == 1.0,\n            "flushed Workflow Step was not retained for the audio callback");\n    require(instance.parameter(kLastCommand) == 1.0 &&\n                instance.parameter(kStatus) == 1.0,\n            "a flushed workflow step did not execute without an audio callback");'''
new_first_flush = '''    std::array<std::vector<float>, 2> gatedSilence{\n        std::vector<float>(48000 * 2), std::vector<float>(48000 * 2)};\n    processCommand(instance.plugin, 2, 0, 64, 0.01);\n    require(instance.parameter(kStatus) == 31.0,\n            "wrong-stage Learn Target mutated workflow state instead of rejecting");\n    flushParameter(instance.plugin, kCaptureReferenceCommand, 0.01);\n    require(instance.parameter(kWorkflowStage) == 1.0 &&\n                instance.parameter(kCaptureReferenceCommand) == 0.0,\n            "fractional flushed Capture Reference did not execute as a momentary action");\n    require(instance.parameter(kLastCommand) == 1.0 &&\n                instance.parameter(kStatus) == 1.0,\n            "a flushed workflow action did not execute without an audio callback");'''
if text.count(old_first_flush) != 1: raise SystemExit('first flush workflow block mismatch')
text = text.replace(old_first_flush, new_first_flush)
text = text.replace('    processCommand(instance.plugin, 0);\n', '')

# Keep the same Reference capture after premature retries; do not use a hidden
# re-arm edge or restart before the successful retry.
text = text.replace('    processSignal(instance.plugin, abandonedCapture, 1);',
                    '    processSignal(instance.plugin, abandonedCapture);', 1)
text = text.replace('        processSignal(instance.plugin, reference, 1);',
                    '        processSignal(instance.plugin, reference);', 1)

old_learn_flush = '''    flushParameter(instance.plugin, kWorkflow, 2.0);\n    require(instance.parameter(kWorkflowStage) == 2.0 &&\n                instance.parameter(kLastCommand) == 2.0 &&\n                instance.parameter(kStatus) == 2.0,\n            "flushed Workflow Step could not advance Reference to Target");\n    processSignal(instance.plugin, target);\n    require(instance.parameter(kConfidence) > 0.0,\n            "target capture did not update live confidence");\n    processCommand(instance.plugin, 3);'''
new_learn_flush = '''    // Stopped-transport path: the exact same Learn Target action that was\n    // rejected above must now succeed through params.flush, with no intervening\n    // workflow-value edge or 30-second wait.\n    instance.plugin->stop_processing(instance.plugin);\n    flushParameter(instance.plugin, kLearnTargetCommand, 0.01);\n    require(instance.parameter(kWorkflowStage) == 2.0 &&\n                instance.parameter(kLearnTargetCommand) == 0.0 &&\n                instance.parameter(kLastCommand) == 2.0 &&\n                instance.parameter(kStatus) == 2.0,\n            "stopped-transport Learn Target retry could not advance Reference to Target");\n    require(instance.plugin->start_processing(instance.plugin),\n            "processing could not restart after stopped-transport workflow test");\n\n    processCommand(instance.plugin, 3, 2, 12000, 0.01);\n    require(instance.parameter(kStatus) == 30.0,\n            "premature Correct Target did not stay on Target with a clear reason");\n    processSignal(instance.plugin, target);\n    require(instance.parameter(kConfidence) > 0.0,\n            "target capture did not update live confidence");\n    processCommand(instance.plugin, 3, 2, 64, 0.01);'''
if text.count(old_learn_flush) != 1: raise SystemExit('Learn Target flush block mismatch')
text = text.replace(old_learn_flush, new_learn_flush)

# A routine snapshot must preserve actual Stage, not a sticky command value.
text = text.replace('"routine host state snapshot cancelled live Reference capture"',
                    '"routine host state snapshot changed live Reference Stage"')
text = text.replace('"routine state snapshot cancelled an incomplete live capture"',
                    '"routine state snapshot changed an incomplete live capture"')

# After a rejected replacement analysis, Stage remains Target for a truthful
# retry; the previously validated correction stays installed but is not falsely
# relabeled Frozen.
old_rejected_freeze = '''    processCommand(restored.plugin, 4);\n    require(restored.parameter(kStatus) == 5.0,\n            "last-known-good correction could not be frozen after rejection");\n#if defined(_WIN32)'''
new_rejected_freeze = '''    require(restored.parameter(kWorkflowStage) == 2.0 &&\n                restored.tail->get(restored.plugin) > 0,\n            "rejected replacement analysis lied about workflow stage or lost the previous correction");\n#if defined(_WIN32)'''
if text.count(old_rejected_freeze) != 1: raise SystemExit('rejected candidate freeze block mismatch')
text = text.replace(old_rejected_freeze, new_rejected_freeze)

# Reset is deliberately no longer encoded as workflow actions 5/6/7. It will be
# covered through the native Options reset callback in the UI workstream.
text, reset_count = re.subn(
    r'\n    processCommand\(restored\.plugin, 5\);.*?\n    restored\.plugin->stop_processing\(restored\.plugin\);',
    '\n    restored.plugin->stop_processing(restored.plugin);', text, count=1, flags=re.S)
if reset_count != 1: raise SystemExit(f'reset workflow block mismatch: {reset_count}')

# Any remaining direct old slider flush is a bug in the rewritten test.
if 'flushParameter(instance.plugin, kWorkflow' in text or 'kWorkflow)' in text or 'kWorkflow,' in text:
    raise SystemExit('legacy kWorkflow reference remains in CLAP tests')

p.write_text(text, encoding='utf-8')
print('workflow regression tests rewritten for explicit actions/stage')
